EXPECTED = {'schema': 'bw.code16-public-semantic.v1', 'passes': 100000, 'instructions': 2400000, 'streamBytes': 80, 'fetchCount': 8000000, 'readCount': 4800000, 'writeCount': 0, 'modelUnits': 2400000, 'cpuCycles': 2400000, 'fetchAddressSum': 524604000000, 'readAddressSum': 1023141800000, 'axAccumulator': 53145700000, 'registers': [3346, 0, 0, 65520, 65534, 32768, 48, 65533], 'eip': 80, 'eflags': 514, 'cr0': 0, 'cr3': 0, 'cr4': 0, 'segments': [16384, 4096, 12288, 8192, 20480, 24576], 'segmentBases': [262144, 65536, 196608, 131072, 327680, 393216], 'memorySha256': '640b843e8fdd4a52f49b85099214fcbd5735055d16d1f227e6136f45cbb3732c', 'faults': 0, 'accelerators': False}

class Refusal(ValueError):
    pass

def require(value,reason):
    if not value:
        raise Refusal(reason)

def exact(value,expected,role):
    require(type(value) is type(expected),role+' type')
    if type(expected) is dict:
        require(value.keys()==expected.keys(),role+' keys')
        for key in expected:exact(value[key],expected[key],role+'.'+key)
    elif type(expected) is list:
        require(len(value)==len(expected),role+' length')
        for index,item in enumerate(expected):exact(value[index],item,role+'.'+str(index))
    else:require(value==expected,role+' value')

ORDERS=('AB','BA','AB','BA','BA','AB','BA')
SCHEDULE=tuple([(index,'warmup',None,arm) for index,arm in enumerate('ABAB')]+
    [(4+pair*2+position,'measured',pair,arm) for pair,order in enumerate(ORDERS) for position,arm in enumerate(order)])

def child(report,arm):
    require(type(report) is dict and set(report)=={'schema','arm','revision','sourceFiles','semantic'},'child fields')
    exact(report['schema'],'bw.code16-public-child.v1','child schema')
    exact(report['arm'],arm,'child arm')
    exact(report['revision'],SOURCES[arm]['revision'],'child revision')
    exact(report['sourceFiles'],SOURCES[arm]['files'],'child source43')
    exact(report['semantic'],EXPECTED,'authored semantic oracle')
    return report['semantic']

def timing(value):
    require(type(value) is dict and set(value)=={'userSeconds','systemSeconds','cpuSeconds','wallSeconds','maxRSSKiB','exitCode','timedOut','reaped','stdoutBytes','stderrBytes'},'timing fields')
    for key in ('userSeconds','systemSeconds','cpuSeconds','wallSeconds'):
        require(type(value[key]) in (int,float) and math.isfinite(value[key]),'finite '+key)
        require(value[key]>0 if key in ('cpuSeconds','wallSeconds') else value[key]>=0,'positive '+key)
    require(value['cpuSeconds']==value['userSeconds']+value['systemSeconds'],'whole child CPU sum')
    require(type(value['maxRSSKiB']) is int and value['maxRSSKiB']>=0,'RSS')
    exact(value['exitCode'],0,'exit')
    exact(value['timedOut'],False,'timeout')
    exact(value['reaped'],True,'reaped')
    require(type(value['stdoutBytes']) is int and 0<value['stdoutBytes']<=262144,'stdout count')
    exact(value['stderrBytes'],0,'stderr count')

def resources(value):
    require(type(value) is dict and set(value)=={'unit','parentCgroup','childCgroup','cpuMax','memoryMax','memorySwapMax','parentAffinity','childAffinity','childPID','memoryEventsBefore','memoryEventsAfter'},'resource fields')
    for key in ('unit','parentCgroup','childCgroup'):require(type(value[key]) is str and 0<len(value[key])<=256,'resource string')
    require(value['unit'].startswith('bw-code16-paired-') and value['unit'].endswith('.service'),'owned unit')
    require(value['parentCgroup']==value['childCgroup'] and value['parentCgroup'].endswith('/'+value['unit']),'same owned cgroup')
    exact(value['cpuMax'],'100000 100000','cpu quota')
    exact(value['memoryMax'],'1073741824','memory quota')
    exact(value['memorySwapMax'],'0','swap quota')
    affinity=value['parentAffinity']
    require(type(affinity) is list and len(affinity)==1 and type(affinity[0]) is int and affinity[0]>=0,'one logical CPU')
    exact(value['childAffinity'],affinity,'child affinity')
    require(type(value['childPID']) is int and value['childPID']>0,'child PID')
    for key in ('memoryEventsBefore','memoryEventsAfter'):
        events=value[key]
        require(type(events) is dict and {'oom','oom_kill','max'}<=set(events),'memory event fields')
        require(all(type(v) is int and v>=0 for v in events.values()),'memory event counts')
    require(value['memoryEventsAfter']==value['memoryEventsBefore'],'no cgroup memory events')

def evaluate(records):
    require(type(records) is list and len(records)==18,'fixed eighteen children')
    paired={};affinity=None;unit=None
    for row,position in zip(records,SCHEDULE):
        require(type(row) is dict and set(row)=={'sequence','phase','pair','arm','child','timing','resources'},'record fields')
        for key,wanted in zip(('sequence','phase','pair','arm'),position):exact(row[key],wanted,'schedule '+key)
        child(row['child'],row['arm']);timing(row['timing']);resources(row['resources'])
        current=(row['resources']['parentAffinity'],row['resources']['parentCgroup'])
        if affinity is None:affinity=current
        else:exact(current[0],affinity[0],'same CPU all children');exact(current[1],affinity[1],'same cgroup all children')
        if row['phase']=='measured':paired.setdefault(row['pair'],{})[row['arm']]=row['timing']
    ratios=[paired[i]['A']['cpuSeconds']/paired[i]['B']['cpuSeconds'] for i in range(7)]
    wall=[paired[i]['B']['wallSeconds']/paired[i]['A']['wallSeconds'] for i in range(7)]
    median=statistics.median(ratios);wall_median=statistics.median(wall)
    passed=median>=1.03 and min(ratios)>1 and wall_median<=1.02
    return {'schema':'bw.code16-public-paired-result.v1','semanticPassed':True,'performancePassed':passed,'cpuRatios':ratios,'wallRatios':wall,'medianCPUSpeedup':median,'minimumCPUSpeedup':min(ratios),'medianWallRatio':wall_median,'conditionalConfidence':0.9921875,'confidenceAssumptions':'independent continuous exchangeable pairs; minimum observed ratio as conditional lower bound','workload':'AUTHORED_PUBLIC_CODE16_24_FORM_MACRO','originalBenchmarkGateSatisfied':False,'adoptionQualified':False,'physicalRTxQualified':False,'fullOSQualified':False}
